pub const RESIDUAL_WRAP_TICKETS: &[&str] = &[
    "AEP28-ENV-012",
    "AEP28-ENV-013",
    "AEP28-ENV-014",
    "AEP28-ENV-015",
];

pub const ADMIT_CRATE_REL: &str = "admit/crate";
pub const SKIP_SELF: &str = "envelope-wrap-journals";

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TicketLanded {
    pub ticket: String,
    pub landed: bool,
    pub evidence: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct WaveReport {
    pub landed: Vec<TicketLanded>,
    pub missing: Vec<String>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct JournalVerdict {
    pub allow: bool,
    pub reason: String,
    pub wave: WaveReport,
}

pub fn ticket_in_source(source: &str, ticket: &str) -> bool {
    source.contains(ticket)
}

pub fn default_components_root() -> PathBuf {
    let dir = std::env::var("CARGO_MANIFEST_DIR").unwrap_or_else(|_| String::from("."));
    PathBuf::from(dir).join("../..")
}

pub fn default_admit_crate() -> PathBuf {
    default_components_root().join(ADMIT_CRATE_REL)
}

fn is_scan_name(name: &str) -> bool {
    name.ends_with(".rs")
        || name.ends_with(".gaplune")
        || name.ends_with(".ts")
        || name.ends_with(".mjs")
        || name.ends_with(".md")
        || name.ends_with(".sh")
}

fn skip_dir_name(name: &str) -> bool {
    name == ".git" || name == "target" || name == "node_modules"
}

fn collect_sources(root: &Path, out: &mut Vec<(String, String)>) {
    let mut stack = Vec::new();
    stack.push(root.to_path_buf());
    while let Some(dir) = stack.pop() {
        let rd = match fs::read_dir(&dir) {
            Ok(v) => v,
            Err(_) => continue,
        };
        for ent in rd.flatten() {
            let path = ent.path();
            let name = path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("")
                .to_string();
            if skip_dir_name(&name) {
                continue;
            }
            if path.is_dir() {
                stack.push(path);
                continue;
            }
            if is_scan_name(&name) == false {
                continue;
            }
            if let Ok(src) = fs::read_to_string(&path) {
                out.push((path.to_string_lossy().into_owned(), src));
            }
        }
    }
}

pub fn evidence_for_ticket(files: &[(String, String)], ticket: &str) -> Option<String> {
    for (path, src) in files {
        if path.contains(SKIP_SELF) {
            continue;
        }
        if ticket_in_source(src, ticket) {
            return Some(path.clone());
        }
    }
    None
}

pub fn scan_wave(root: &Path) -> WaveReport {
    let mut files = Vec::new();
    collect_sources(root, &mut files);
    let mut landed = Vec::new();
    let mut missing = Vec::new();
    for ticket in RESIDUAL_WRAP_TICKETS {
        if let Some(ev) = evidence_for_ticket(&files, ticket) {
            landed.push(TicketLanded {
                ticket: (*ticket).to_string(),
                landed: true,
                evidence: ev,
            });
            continue;
        }
        missing.push((*ticket).to_string());
        landed.push(TicketLanded {
            ticket: (*ticket).to_string(),
            landed: false,
            evidence: String::new(),
        });
    }
    WaveReport { landed, missing }
}

pub fn journal_allow(wave: &WaveReport) -> JournalVerdict {
    if wave.missing.is_empty() {
        JournalVerdict {
            allow: true,
            reason: String::from(
                "residual wrap wave landed; journals allowed on residual wrap crates",
            ),
            wave: wave.clone(),
        }
    } else {
        let mut reason = String::from(
            "journals denied until residual wrap tickets land; journals for that residual are not due: ",
        );
        reason.push_str(&wave.missing.join(","));
        JournalVerdict {
            allow: false,
            reason,
            wave: wave.clone(),
        }
    }
}

pub fn run_gate(root: &Path) -> JournalVerdict {
    let wave = scan_wave(root);
    journal_allow(&wave)
}

pub fn format_verdict(v: &JournalVerdict) -> String {
    let mut out = String::new();
    if v.allow {
        out.push_str("allow\n");
    } else {
        out.push_str("deny\n");
    }
    out.push_str(&v.reason);
    out.push('\n');
    for t in &v.wave.landed {
        out.push_str(&t.ticket);
        if t.landed {
            out.push_str(" landed ");
            out.push_str(&t.evidence);
        } else {
            out.push_str(" missing");
        }
        out.push('\n');
    }
    out
}

fn err_msg(msg: String) -> anyhow::Error {
    anyhow::Error::msg(msg)
}

