#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::path::PathBuf;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn must(cond: bool) {
        if cond == false {
            std::process::abort();
        }
    }

    fn temp_root(tag: &str) -> PathBuf {
        let n = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(1);
        let mut name = String::from("aep-env-016-");
        name.push_str(tag);
        name.push('-');
        name.push_str(&n.to_string());
        let p = PathBuf::from("/tmp").join(name);
        let _ = fs::create_dir_all(&p);
        p
    }

    fn write_file(root: &Path, rel: &str, body: &str) {
        let p = root.join(rel);
        if let Some(parent) = p.parent() {
            let _ = fs::create_dir_all(parent);
        }
        fs::write(&p, body.as_bytes()).expect("write fixture");
    }

    fn plant_wave(root: &Path) {
        write_file(
            root,
            "envelope-wrap-disabled/aep-registration.gaplune",
            "ticket: AEP28-ENV-012\n",
        );
        write_file(
            root,
            "live-crossing-lab-off/aep-registration.gaplune",
            "ticket: AEP28-ENV-013\n",
        );
        write_file(
            root,
            "process-event-admit-walls/aep-registration.gaplune",
            "ticket: AEP28-ENV-014\n",
        );
        write_file(
            root,
            "live-crossing-reject-copy/aep-registration.gaplune",
            "ticket: AEP28-ENV-015\n",
        );
    }

    #[test]
    fn ticket_in_source_detects_registration() {
        must(ticket_in_source("ticket: AEP28-ENV-012\n", "AEP28-ENV-012") == true);
        must(ticket_in_source("ticket: AEP28-ENV-013\n", "AEP28-ENV-012") == false);
    }

    #[test]
    fn missing_tickets_deny_journals() {
        let root = temp_root("missing");
        write_file(&root, "only.md", "nothing\n");
        let v = run_gate(&root);
        must(v.allow == false);
        must(v.wave.missing.is_empty() == false);
        must(v.reason.contains("journals for that residual are not due") == true);
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn full_wave_allows_journals() {
        let root = temp_root("full");
        plant_wave(&root);
        let v = run_gate(&root);
        must(v.allow == true);
        must(v.wave.missing.is_empty() == true);
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn journal_before_wave_denied() {
        let root = temp_root("before");
        write_file(
            &root,
            "envelope-wrap-disabled/crate/src/lib.rs",
            "// AEP28-ENV-012\n",
        );
        let v = run_gate(&root);
        must(v.allow == false);
        must(v.reason.contains("journals denied") == true);
        let mut gate = residual_wrap_journal_gate::ResidualWrapJournalGate::new();
        gate.wave = root.to_string_lossy().into_owned();
        must(gate.process().is_err() == true);
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn self_crate_does_not_count_as_landing() {
        let root = temp_root("self");
        write_file(
            &root,
            "envelope-wrap-journals/crate/src/lib.rs",
            "ticket: AEP28-ENV-012\nticket: AEP28-ENV-013\nticket: AEP28-ENV-014\nticket: AEP28-ENV-015\n",
        );
        let v = run_gate(&root);
        must(v.allow == false);
        must(v.wave.missing.len() == 4);
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn modules_process_on_planted_wave() {
        let root = temp_root("mods");
        plant_wave(&root);
        let mut one = residual_wrap_ticket_landed::ResidualWrapTicketLanded::new();
        one.ticket = String::from("AEP28-ENV-012");
        one.source = String::from("ticket: AEP28-ENV-012\n");
        must(one.process().is_ok() == true);
        must(one.landed.as_str() == "true");
        let mut wave = residual_wrap_wave_landed::ResidualWrapWaveLanded::new();
        wave.tree = root.to_string_lossy().into_owned();
        must(wave.process().is_ok() == true);
        let mut gate = residual_wrap_journal_gate::ResidualWrapJournalGate::new();
        gate.wave = root.to_string_lossy().into_owned();
        must(gate.process().is_ok() == true);
        must(gate.allow.as_str() == "true");
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn live_components_tree_when_present() {
        let root = default_components_root();
        if root.is_dir() == false {
            return;
        }
        let v = run_gate(&root);
        if v.allow == false {
            let formatted = format_verdict(&v);
            must(formatted.contains("deny") == true);
            must(v.reason.contains("not due") == true);
            return;
        }
        must(v.allow == true);
        must(v.wave.missing.is_empty() == true);
    }
}
